import java.util.*;

public class HierarchyDemo {
    public static void main(String[] args) {
        // Iterable: the root - anything you can loop over
        Iterable<String> iterable = List.of("A", "B");

        // Collection extends Iterable: add/remove/size/contains
        Collection<String> col = new ArrayList<>();
        col.add("order-1");

        // List branch: ordered, indexed, duplicates allowed
        List<String> list = new ArrayList<>(col);
        String first = list.get(0); // positional access

        // Set branch: rejects duplicates
        Set<String> set = new HashSet<>(list);

        // Queue branch: FIFO processing
        Queue<String> queue = new LinkedList<>();
        queue.offer("task-1");

        // Map: SEPARATE hierarchy - key/value, not under Collection
        Map<String, Integer> prices = new HashMap<>();
        prices.put("order-1", 100);

        // Map bridges back via Collection views
        Set<String> keys = prices.keySet();
        Collection<Integer> vals = prices.values();
    }
}
