import java.util.*;

// Generates IDs on the fly - no storage, not a Collection,
// yet works with for-each because it implements Iterable.
class OrderIdRange implements Iterable<String> {
    private final int start, end;
    OrderIdRange(int start, int end) { this.start = start; this.end = end; }

    @Override public Iterator<String> iterator() {
        return new Iterator<>() {
            private int cur = start;
            @Override public boolean hasNext() { return cur < end; }
            @Override public String next() {
                if (!hasNext()) throw new NoSuchElementException();
                return "ORDER-" + (cur++);
            }
        };
    }

    public static void main(String[] args) {
        for (String id : new OrderIdRange(100, 103)) {
            System.out.println(id);   // ORDER-100, ORDER-101, ORDER-102
        }
    }
}
