import java.util.*;

public class PickImpl {
    public static void main(String[] args) {
        // List: indexed access -> ArrayList
        List<String> products = new ArrayList<>();
        products.add("P-1");
        String p = products.get(0);              // O(1)

        // List as a queue/deque -> LinkedList
        Deque<String> tasks = new LinkedList<>();
        tasks.addFirst("t1"); tasks.addLast("t2");

        // Set: fast membership, no order -> HashSet
        Set<String> seen = new HashSet<>();
        seen.add("u1"); boolean has = seen.contains("u1"); // O(1)

        // Set: sorted iteration -> TreeSet
        Set<String> sorted = new TreeSet<>(List.of("c", "a", "b")); // [a, b, c]

        // Map: fast lookup by id -> HashMap
        Map<String, Integer> price = new HashMap<>();
        price.put("P-1", 100);

        // Map: keep insertion order -> LinkedHashMap
        Map<String, Integer> ordered = new LinkedHashMap<>();

        // Map: sorted keys / range queries -> TreeMap
        TreeMap<Integer, String> byId = new TreeMap<>();
        byId.put(3, "c"); byId.put(1, "a");
        SortedMap<Integer, String> firstTwo = byId.headMap(3); // range query
    }
}
